100	/** The pinned migrated build record, re-read rather than restated. */
101	async function migratedLaneRecord(): Promise<{
102		inventory: InventoryEntry[];
103		inventorySha256: string;
104	}> {
105		const pinned = ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS.find(
106			(receipt) => receipt.lane === 'migrated',
107		);
108		if (pinned === undefined) throw new Error('TinyTranslator migrated lane binding is absent');
109		const bytes = await readFile(join(root, pinned.path));
110		if (sha256(bytes) !== pinned.sha256)
111			throw new Error(`TinyTranslator bound build receipt bytes drifted: ${pinned.path}`);
112		const record = JSON.parse(bytes.toString('utf8')) as {
113			inventory?: InventoryEntry[];
114			determinism?: { inventorySha256?: string };
115		};
116		const inventory = record.inventory;
117		const inventorySha256 = record.determinism?.inventorySha256;
118		if (!Array.isArray(inventory) || typeof inventorySha256 !== 'string')
119			throw new Error('TinyTranslator migrated lane record publishes no inventory to verify');
120		return { inventory, inventorySha256 };
121	}
