125	 * JSON array with a trailing newline, exactly as the recording flow wrote it.
126	 * Recomputing it here rather than accepting the record's own number is what
127	 * makes the comparison a check instead of a restatement.
128	 */
129	function inventoryDigest(inventory: readonly InventoryEntry[]): string {
130		return sha256(`${JSON.stringify(inventory, null, 2)}\n`);
131	}
132	
133	async function run(command: string, args: readonly string[], cwd: string): Promise<void> {
134		await new Promise<void>((settle, fail) => {
135			const child = spawn(command, [...args], {
136				cwd,
137				stdio: 'ignore',
138				env: {
139					...process.env,
140					VERSIONLESS_NETWORK_MODE: 'offline',
141					NPM_CONFIG_OFFLINE: 'true',
142				},
143			});
144			child.on('error', fail);
145			child.on('close', (code) =>
146				code === 0
147					? settle()
148					: fail(new Error(`TinyTranslator regeneration command failed: ${command} (${code})`)),
149			);
150		});
151	}
152	
153	/**
154	 * The migrated lane's canonical output root, regenerated when it is missing and
155	 * verified either way.
156	 *
157	 * The regeneration is the same offline production build the u19f record pins,
158	 * run over the same staged application tree that record itemises; nothing is
159	 * re-migrated here, because the migration is already applied in that tree. The
160	 * verification is what the proof actually rests on: the emitted inventory has
161	 * to reproduce the record's own 524-file inventory, file for file and digest
162	 * for digest, and its digest has to reproduce the record's `inventorySha256`.
163	 * A tree that regenerated differently is refused rather than served.
164	 */
165	async function migratedLaneRoot(): Promise<string> {
166		const record = await migratedLaneRecord();
167		if (!(await exists(sourceOutputs.migrated))) {
168			const application = join(migratedStage, 'app');
169			if (!(await exists(application)))
170				throw new Error(
171					'TinyTranslator migrated lane cannot be regenerated: the staged application tree is absent',
172				);
173			const [command, ...args] = MIGRATED_BUILD_COMMAND.split(' ');
174			await run(command!, [...args, '--output-path', sourceOutputs.migrated], application);
175		}
176		const emitted = await inventoryOf(sourceOutputs.migrated);
177		const emittedDigest = inventoryDigest(emitted);
178		if (canonicalize(emitted) !== canonicalize(record.inventory))
179			throw new Error(
180				`TinyTranslator migrated lane inventory differs from the pinned record: ${emittedDigest} against ${record.inventorySha256}`,
