221				const candidate = raw as WitnessAngularTinyTranslatorRun;
222				if (candidate.semanticDigest !== witnessAngularTinyTranslatorRawDigest(candidate))
223					throw new Error(`TinyTranslator ${lane} pass ${pass} raw digest differs`);
224				runs.push({
225					...candidate,
226					behaviorDigest: witnessAngularTinyTranslatorBehaviorDigest(candidate),
227				});
228			}
229		if (new Set(runs.map((entry) => entry.behaviorDigest)).size !== 1)
230			throw new Error('TinyTranslator baseline/migrated behavior parity differs');
231		return runs;
232	}
