234	/**
235	 * Byte mutation on the migrated build.
236	 *
237	 * The seam is the visible label of the control that opens the file picker: a
238	 * string a reader sees, asserted exactly by the journey on the create-project
239	 * route, and the name of the very mechanism this vertical exists to exercise.
240	 * The uniqueness demanded here is the corpus discipline — exactly one served
241	 * module may carry it, exactly once — so overwriting it in place cannot be
242	 * absorbed by a second copy elsewhere in the bundle.
243	 */
244	async function semanticMutation(
245		laneRoot: string,
246		behaviorDigest: string,
247	): Promise<WitnessAngularTinyTranslatorMutation> {
248		const expected = Buffer.from(TINY_TRANSLATOR_MUTATION_SEAM);
249		const candidates: Array<{ path: string; offset: number }> = [];
250		for (const path of await files(laneRoot)) {
251			const bytes = await readFile(path);
252			const offset = bytes.indexOf(expected);
253			if (offset < 0) continue;
254			if (bytes.lastIndexOf(expected) !== offset)
255				throw new Error('TinyTranslator semantic seam is not unique within its file');
256			candidates.push({ path, offset });
257		}
258		const target = candidates[0];
259		if (candidates.length !== 1 || target === undefined || !target.path.endsWith('.js'))
260			throw new Error('TinyTranslator semantic seam is not a single served module');
261		const before = await readFile(target.path);
262		const mutated = Buffer.from(before);
263		Buffer.alloc(expected.length, 'X').copy(mutated, target.offset);
264		const beforeSha256 = sha256(before);
265		const mutatedSha256 = sha256(mutated);
266		let intendedFailure = false;
267		try {
268			await writeFile(target.path, mutated);
269			try {
270				await executeAngularTinyTranslatorWitnessRun({
271					lane: 'migrated',
272					pass: 1,
273					laneRoot,
274					receiptRoot: join(stageRoot, 'mutation-receipt'),
275				});
276			} catch (error) {
277				const message = error instanceof Error ? error.message : String(error);
278				intendedFailure = message.includes(TINY_TRANSLATOR_MUTATION_SEAM);
279			}
280		} finally {
281			await writeFile(target.path, before);
282		}
283		const afterRestoreSha256 = sha256(await readFile(target.path));
284		if (!intendedFailure || afterRestoreSha256 !== beforeSha256)
285			throw new Error('TinyTranslator semantic mutation was not exact red and byte-restored');
286		const restored = (await executeAngularTinyTranslatorWitnessRun({
287			lane: 'migrated',
288			pass: 1,
289			laneRoot,
290			receiptRoot: join(stageRoot, 'restoration-receipt'),
291		})) as WitnessAngularTinyTranslatorRun;
292		const restoredBehaviorDigest = witnessAngularTinyTranslatorBehaviorDigest(restored);
293		if (restoredBehaviorDigest !== behaviorDigest)
294			throw new Error('TinyTranslator restored browser behavior differs');
295		return {
296			failure: 'witness-semantic-assertion',
297			intendedFailure: true,
298			lane: 'migrated',
299			seam: TINY_TRANSLATOR_MUTATION_SEAM,
300			path: relative(laneRoot, target.path),
301			offset: target.offset,
302			beforeSha256,
303			mutatedSha256,
304			afterRestoreSha256,
305			restoredByteIdentically: true,
306			restoredRun: 'pass',
307			restoredBehaviorDigest,
308		};
309	}
