311	/**
312	 * The nonclaims this proof publishes. Each one names something a reader could
313	 * otherwise assume from the rest of the receipt and states plainly that it is
314	 * not established here.
315	 */
316	export const WITNESS_ANGULAR_TINY_TRANSLATOR_NONCLAIMS: readonly string[] = Object.freeze([
317		'This is one Angular lineage under direct Witness and does not establish generic Angular, Angular CLI 1.5, `.angular-cli.json` workspaces, or `@angular-devkit/build-angular:browser` support.',
318		'The Angular lineage readiness score is unchanged; this vertical is not counted before Judge audit.',
319		'There is no backend and nothing was stubbed or seeded by the harness. The project the journey works on is created by the application itself, from a file this proof hands its own file input, and everything it keeps it keeps in browser local storage.',
320		'The translation file handed to the page is synthetic and authored for this proof. It carries no upstream project’s strings and no third party’s translated content, and it is bound by name, length and digest so a journey cannot quietly load a different one.',
321		'The file the page produced is read back by name, byte length and digest, and its content is asserted rather than published: a produced translation file is the application’s data, not this receipt’s.',
322		'Neither lane ends up with the Material Icons glyphs, and the two lanes fail to get them differently. Both degradations are measured and recorded rather than masked, and neither is a regression of the migration: the font seam is answered inside the browser context so that nothing leaves the machine.',
323		'Two of the four rendered-appearance probes are declared to differ across the eleven-major lift and are checked in both directions — a probe outside the declaration that differs fails the run, and a declared difference that stopped being real fails it too.',
324		'Byte parity across the lanes is not claimed and is recorded separately by the bound build receipts; eleven majors of bundler produce different file names and different byte counts by construction.',
325		'Neither build ships a service worker, and BOTH attempt to register one. The application registers at the literal `%BASE_HREF%ngsw-worker.js` — a placeholder upstream substitutes in a separate npm script that `ng build` never runs — and the request is answered 400 in both lanes. It is an era defect that survives the migration: the migration did not introduce it and no capability here repaired it, and it is recorded rather than suppressed.',
326		'Locality is process-scoped and does not establish operating-system-wide isolation.',
327		'Receipts prove reproducibility and hash integrity, not certification, authenticity, signer identity, compliance, or an earned SLSA level.',
328	]);
