330	async function bindCanonicalReceipts(): Promise<
331		WitnessAngularTinyTranslatorReceipt['canonicalReceipts']
332	> {
333		return await Promise.all(
334			ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS.map(async (pinned) => {
335				const bytes = await readFile(join(root, pinned.path));
336				const value = JSON.parse(bytes.toString('utf8')) as {
337					schemaVersion?: unknown;
338					digest?: unknown;
339				};
340				if (
341					value.schemaVersion !== pinned.schemaVersion ||
342					value.digest !== pinned.digest ||
343					sha256(bytes) !== pinned.sha256
344				)
345					throw new Error(
346						`TinyTranslator bound build receipt identity differs: ${pinned.path}`,
347					);
348				return { ...pinned };
349			}),
350		);
351	}
352	
353	export async function runWitnessAngularTinyTranslator(): Promise<WitnessAngularTinyTranslatorReceipt> {
354		if (
355			process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
356			process.env.NPM_CONFIG_OFFLINE !== 'true'
357		)
358			throw new Error('TinyTranslator Witness requires dual offline controls');
359		if (await exists(witnessEvidence))
360			throw new Error('TinyTranslator Witness output collision');
361		const provenance = await verifyLinkedWitnessProvenance(root);
362		const canonicalReceipts = await bindCanonicalReceipts();
363		const lanes = await stageInputs();
364		const runs = await executeRuns(lanes);
365		const mutation = await semanticMutation(lanes.migrated, runs[0]!.behaviorDigest);
366		const baseline = runs.find((entry) => entry.lane === 'baseline')!;
367		const migrated = runs.find((entry) => entry.lane === 'migrated')!;
368		const artifacts = join(fixtureEvidence, 'witness-artifacts');
369		await mkdir(artifacts, { recursive: true });
370		await writeFile(join(artifacts, 'witness-journeys.json'), `${canonicalize(runs)}\n`, {
371			flag: 'wx',
372		});
373		await writeFile(join(artifacts, 'witness-mutation.json'), `${canonicalize(mutation)}\n`, {
374			flag: 'wx',
375		});
376		const receipt: WitnessAngularTinyTranslatorReceipt = {
377			schemaVersion: WITNESS_ANGULAR_TINY_TRANSLATOR_SCHEMA,
378			result: 'pass',
379			fixture: ANGULAR_TINY_TRANSLATOR_FIXTURE,
380			source: ANGULAR_TINY_TRANSLATOR_SOURCE,
381			provenance,
382			canonicalReceipts,
383			runs,
384			mutation,
385			consoleErrors: {
386				baseline: [...WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS.baseline],
387				migrated: [...WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS.migrated],
388			},
389			failedRequests: {
390				baseline: [...WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS.baseline],
391				migrated: [...WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS.migrated],
392			},
393			mockedSeams: {
394				baseline: [...baseline.mockedNonLoopbackSeams.category],
395				migrated: [...migrated.mockedNonLoopbackSeams.category],
396			},
397			fontSeamDifference: WITNESS_ANGULAR_TINY_TRANSLATOR_FONT_SEAM_DIFFERENCE,
398			serviceWorkerAttempt: WITNESS_ANGULAR_TINY_TRANSLATOR_SERVICE_WORKER_ATTEMPT,
399			matIconDegradations: {
400				baseline: baseline.applicationJourney.matIcon,
401				migrated: migrated.applicationJourney.matIcon,
402			},
403			renderedStyleParity: {
404				state: 'measured-resolved-styles-with-declared-differences',
405				probes: WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_PROBES.length,
406				declaredDifferences: WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_DIFFERENCES,
407				otherProbesAgree: true,
408			},
409			fileInput: {
410				surfaces: WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_SURFACES,
411				fixture: WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE,
412				rule: WITNESS_FILE_INPUT_LOAD_RULE,
413			},
414			downloads: {
415				surface: WITNESS_ANGULAR_TINY_TRANSLATOR_DOWNLOAD_SURFACE,
416				rule: WITNESS_DOWNLOAD_CAPTURE_RULE,
417				captured: runs.map((entry) => ({
418					lane: entry.lane,
419					pass: entry.pass,
420					files: [...entry.downloadCaptures.captured],
421				})),
422			},
423			persistence: {
424				store: 'browser-local-storage',
425				backend: 'none',
426				stubbed: false,
427				survivesOnlineReload: true,
428			},
429			routeShape: WITNESS_ANGULAR_TINY_TRANSLATOR_ROUTE_SHAPE,
430			scrollAbsence: runs[0]!.scrollAbsence,
431			accommodations: WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS,
432			readiness: {
433				angularLineage: { ready: 1, total: 4, counted: false },
434				overall: { ready: 3, total: 12 },
435			},
436			locality: {
437				mode: 'offline',
438				successfulNonLoopback: 0,
439				osWideIsolation: false,
440				mockedNonLoopbackSeams: migrated.mockedNonLoopbackSeams.category.length,
441			},
442			nonclaims: [...WITNESS_ANGULAR_TINY_TRANSLATOR_NONCLAIMS],
443			integrity: { algorithm: 'sha256', canonicalDigest: '' },
444		};
445		receipt.integrity.canonicalDigest = witnessAngularTinyTranslatorDigest(receipt);
446		parseWitnessAngularTinyTranslatorReceipt(receipt);
447		await mkdir(witnessEvidence, { recursive: true });
448		const canonical = canonicalize(receipt);
449		/**
450		 * The companion is rendered from the receipt as PUBLISHED rather than from
451		 * the object in memory: canonicalization sorts keys, so a companion rendered
452		 * from the in-memory object would disagree with the same companion rendered
453		 * from the file, and `verify` — which only ever has the file — would be
454		 * right to reject it.
455		 */
456		const published = parseWitnessAngularTinyTranslatorReceipt(JSON.parse(canonical));
457		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonical}\n`, { flag: 'wx' });
458		await writeFile(
459			join(witnessEvidence, 'receipt.md'),
460			renderWitnessAngularTinyTranslatorReceipt(published),
461			{ flag: 'wx' },
462		);
463		return published;
464	}
465	
466	export async function verifyWitnessAngularTinyTranslator(
467		output = witnessEvidence,
468	): Promise<WitnessAngularTinyTranslatorReceipt> {
469		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
470		const receipt = parseWitnessAngularTinyTranslatorReceipt(
471			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
472		);
473		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
474			throw new Error('TinyTranslator linked Witness provenance differs');
475		for (const bound of receipt.canonicalReceipts)
476			if (sha256(await readFile(join(root, bound.path))) !== bound.sha256)
477				throw new Error(`TinyTranslator bound build receipt bytes drifted: ${bound.path}`);
478		if (
479			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
480			renderWitnessAngularTinyTranslatorReceipt(receipt)
481		)
482			throw new Error('TinyTranslator human Witness receipt differs');
483		const serialized = canonicalize(receipt);
484		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
485			throw new Error('TinyTranslator receipt leaks host identity');
486		return receipt;
487	}
488	
489	export async function main(args = process.argv.slice(2)): Promise<void> {
490		const publishIndex = args.indexOf('--publish');
491		const verifyIndex = args.indexOf('--verify');
492		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
493			const output = resolve(root, args[publishIndex + 1]!);
494			if (output !== witnessEvidence) throw new Error('TinyTranslator publish path differs');
495			const receipt = await runWitnessAngularTinyTranslator();
496			process.stdout.write(
497				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
498			);
499			return;
500		}
501		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
502			const receipt = await verifyWitnessAngularTinyTranslator(
503				resolve(root, args[verifyIndex + 1]!),
504			);
505			process.stdout.write(
506				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
507			);
508			return;
509		}
510		throw new Error(
511			'TinyTranslator Witness runner requires --run-twice --publish <dir> or --verify <dir>',
512		);
513	}
514	
515	if (basename(process.argv[1] ?? '') === 'angular-tiny-translator-run.ts')
516		main().catch((error: unknown) => {
517			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
518			process.exitCode = 1;
519		});

