 92			label: 'registerOnChange',
 93			find: 'registerOnChange(e){this.propagateChange=e}',
 94			replace:
 95				"registerOnChange(e){window.__P.ev.push({k:'registerOnChange',ro:!!this.readonly," +
 96				't:Math.round(performance.now())}),this.propagateChange=e}',
 97		}),
 98		Object.freeze({
 99			label: 'valueChanged',
100			find: 'valueChanged(e){if(!this.readonly&&this.message)',
101			replace:
102				"valueChanged(e){window.__P.ev.push({k:'valueChanged',ro:!!this.readonly," +
103				't:Math.round(performance.now())});if(!this.readonly&&this.message)',
104		}),
