264			declared: true,
265			manifest: serializeJson({ ...parsed, dependencies: next }),
266			change: Object.freeze({
267				field: 'dependencies',
268				name: LOCALIZE_PACKAGE,
269				from: current ?? null,
270				to: range,
271			}),
272			entryPoint: LOCALIZE_POLYFILL_ENTRY_POINT,
273			reading,
274			declaredDifferences: Object.freeze(declaredDifferences),
275			unhandled: Object.freeze([]),
276		});
