  1	/**
  2	 * `entryComponents` in an `@NgModule` literal.
  3	 *
  4	 * Before Ivy, a component created dynamically rather than named in a template
  5	 * had to be listed in `entryComponents` or the View Engine compiler emitted no
  6	 * factory for it. Ivy generates a definition for every declared component, the
  7	 * concept became meaningless in Angular 9, and Angular 13 removed the property
  8	 * from the `NgModule` type — so a literal that still carries it fails to
  9	 * type-check against `NgModule`.
 10	 *
 11	 * The property has no successor. There is nowhere to move the list to, and the
 12	 * only correct edit is to drop it. That makes the interesting question not
 13	 * *how* to rewrite but *whether* the drop is safe, and this capability answers
 14	 * it before it edits: every component the list names must be reachable from the
 15	 * same module literal without it — declared in `declarations`, or bootstrapped
 16	 * in `bootstrap`. Both are resolved as bindings, so a name that happens to
 17	 * repeat in an unrelated array does not count and an aliased import does.
 18	 *
 19	 * A component named only by `entryComponents` is refused by name. Dropping the
 20	 * property there would be the one case where the removal is not an equivalence:
 21	 * the module would compile and the component would not be part of it. Refusal
 22	 * is per module literal and total.
 23	 *
 24	 * Nothing here is application specific. A literal with no `entryComponents` is
 25	 * reported unchanged, which is what every post-Ivy module produces.
 26	 */
 27	
 28	import { compareStrings } from './angular-target-cell.ts';
 29	import {
 30		applySourceEdits,
 31		denotesExport,
 32		forEachNode,
 33		lineOf,
 34		parseModule,
 35		plainProperties,
 36		readModuleImports,
 37		type AstNode,
 38		type SemanticModule,
 39		type SourceEdit,
 40	} from './semantic-module.ts';
 41	
 42	const CAPABILITY = 'Entry components removal';
 43	
 44	/** The package that publishes the decorator, and the property Angular removed. */
 45	export const NG_MODULE_PACKAGE = '@angular/core';
 46	export const NG_MODULE_DECORATOR = 'NgModule';
 47	export const REMOVED_PROPERTY = 'entryComponents';
 48	
 49	/** The properties whose members Angular reaches without an entry-component list. */
 50	export const REACHING_PROPERTIES: readonly string[] = Object.freeze(['declarations', 'bootstrap']);
 51	
 52	export type EntryComponentsChange = Readonly<{
 53		kind: 'entry-components-removal';
 54		line: number;
 55		symbols: readonly string[];
 56	}>;
 57	
 58	export type EntryComponentsMigration = Readonly<{
 59		path: string;
 60		source: string;
 61		changed: boolean;
 62		changes: readonly EntryComponentsChange[];
 63		unhandled: readonly string[];
 64	}>;
 65	
 66	/**
 67	 * The bindings an array-literal property of the module names, or null when the
 68	 * property is present but is not a plain array of resolvable identifiers.
 69	 */
 70	function bindingsOf(module: SemanticModule, value: AstNode): ReadonlySet<unknown> | null {
 71		if (value.type !== 'ArrayExpression') return null;
 72		const symbols = new Set<unknown>();
 73		for (const element of value.elements) {
 74			if (element === null) continue;
 75			if (element.type !== 'Identifier') return null;
 76			const symbol = module.symbolOf(element);
 77			if (symbol === null) return null;
 78			symbols.add(symbol);
 79		}
 80		return symbols;
 81	}
 82	
 83	/**
 84	 * The span to delete for one property of an object literal, including the
 85	 * separator that would otherwise be left dangling.
 86	 *
 87	 * A property that owns its line is removed with the line, so the literal keeps
 88	 * the shape it had. A property sharing a line with others loses only itself and
 89	 * one separator.
 90	 */
 91	function removalSpan(source: string, property: AstNode): SourceEdit {
 92		let start = property.start;
 93		while (start > 0) {
 94			const previous = source[start - 1];
 95			if (previous !== ' ' && previous !== '\t') break;
 96			start -= 1;
 97		}
 98		let end = property.end;
 99		while (end < source.length && (source[end] === ' ' || source[end] === '\t')) end += 1;
100		let separated = false;
101		if (source[end] === ',') {
102			end += 1;
103			separated = true;
104		}
105		if (!separated) {
106			// Last property in the literal: the separator to absorb is the one before it.
107			let back = start;
108			while (back > 0 && /\s/u.test(source[back - 1] ?? '')) back -= 1;
109			if (source[back - 1] === ',') start = back - 1;
110			return Object.freeze({ start, end, text: '' });
111		}
112		let after = end;
113		while (after < source.length && (source[after] === ' ' || source[after] === '\t')) after += 1;
114		if (source[after] === '\n' && (start === 0 || source[start - 1] === '\n'))
115			return Object.freeze({ start, end: after + 1, text: '' });
116		return Object.freeze({ start, end, text: '' });
117	}
118	
119	/**
120	 * Drop `entryComponents` from every `@NgModule` literal in the module whose
121	 * components the same literal already reaches.
122	 */
123	export function removeEntryComponents(path: string, source: string): EntryComponentsMigration {
124		const module = parseModule(CAPABILITY, path, source);
125		const core = readModuleImports(module, NG_MODULE_PACKAGE);
126		const edits: SourceEdit[] = [];
127		const changes: EntryComponentsChange[] = [];
128		const unhandled: string[] = [];
129		if (!core.present)
130			return Object.freeze({
131				path,
132				source,
133				changed: false,
134				changes: Object.freeze([]),
135				unhandled: Object.freeze([]),
136			});
137		forEachNode(module.ast, (node) => {
138			if (node.type !== 'Decorator') return;
139			const call = node.expression;
140			if (call.type !== 'CallExpression') return;
141			if (!denotesExport(module, call.callee, core, NG_MODULE_DECORATOR)) return;
142			const literal = call.arguments[0];
143			if (literal === undefined || literal.type !== 'ObjectExpression') return;
144			const line = lineOf(source, node.start);
145			const properties = plainProperties(literal);
146			if (properties === null) {
147				unhandled.push(
148					`${path} line ${String(line)}: the @${NG_MODULE_DECORATOR} literal carries a spread, a ` +
149						'computed key or an accessor, so what it does and does not declare cannot be read ' +
150						'from it, and it was left exactly as it is',
151				);
152				return;
153			}
154			const removed = properties.find((property) => property.name === REMOVED_PROPERTY);
155			if (removed === undefined) return;
156			const listed = bindingsOf(module, removed.value);
157			if (listed === null) {
158				unhandled.push(
159					`${path} line ${String(line)}: ${REMOVED_PROPERTY} is not a plain array of resolvable ` +
160						'identifiers, so which components it names cannot be read, and the property was left ' +
161						'exactly as it is',
162				);
163				return;
164			}
165			const reaching = new Set<unknown>();
166			for (const name of REACHING_PROPERTIES) {
167				const property = properties.find((candidate) => candidate.name === name);
168				if (property === undefined) continue;
169				const bindings = bindingsOf(module, property.value);
170				if (bindings === null) {
171					unhandled.push(
172						`${path} line ${String(line)}: ${name} is not a plain array of resolvable identifiers, ` +
173							`so it cannot be used to prove that a ${REMOVED_PROPERTY} entry stays reachable, and ` +
174							'the property was left exactly as it is',
175					);
176					return;
177				}
178				for (const binding of bindings) reaching.add(binding);
179			}
180			const names: string[] = [];
181			const stranded: string[] = [];
182			if (removed.value.type === 'ArrayExpression')
183				for (const element of removed.value.elements) {
184					if (element === null || element.type !== 'Identifier') continue;
185					names.push(element.name);
186					if (!reaching.has(module.symbolOf(element))) stranded.push(element.name);
187				}
188			if (stranded.length > 0) {
189				unhandled.push(
190					`${path} line ${String(line)}: ${stranded.sort(compareStrings).join(', ')} ` +
191						`${stranded.length === 1 ? 'is named' : 'are named'} by ${REMOVED_PROPERTY} and by ` +
192						`neither ${REACHING_PROPERTIES.join(' nor ')} of the same module. Dropping the ` +
193						'property would remove them from the module rather than leave them where Ivy ' +
194						'already reaches them, so it was left exactly as it is.',
195				);
196				return;
197			}
198			edits.push(removalSpan(source, removed.node));
199			changes.push({
200				kind: 'entry-components-removal',
201				line: lineOf(source, removed.node.start),
202				symbols: Object.freeze([...names].sort(compareStrings)),
203			});
204		});
205		const migrated = applySourceEdits(source, edits);
206		return Object.freeze({
207			path,
208			source: migrated,
209			changed: migrated !== source,
210			changes: Object.freeze(changes),
211			unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
212		});
213	}

