}

/** The indentation of the line `offset` sits on. */
function indentAt(source: string, offset: number): string {
	const start = source.lastIndexOf('\n', offset - 1) + 1;
	const line = source.slice(start, offset);
	return /^[ \t]*/u.exec(line)?.[0] ?? '';
