/**
 * Bring `CALL_SET_DISABLED_STATE` into scope, reusing the declaration the module
 * already has for `@angular/forms` rather than writing a second one for the same
 * specifier — a shape the application did not write.
 */
function tokenImport(
	module: SemanticModule,
	source: string,
	name: string,
): Readonly<{ edit: SourceEdit; added: boolean }> | null {
	for (const node of module.ast.body) {
