	const { module, parsed, literal, line } = root;
	const source = module.source;
	const properties = plainProperties(literal)!;
	const providers = properties.find((property) => property.name === 'providers');
	if (providers === undefined || providers.value.type !== 'ArrayExpression')
		return refusal(
			[
				`${CALL_SET_DISABLED_STATE_TOKEN} was not provided: the bootstrapping ` +
					`@${NG_MODULE_DECORATOR} literal in ${module.path} carries ` +
					(providers === undefined
						? 'no `providers` property'
						: 'a `providers` value that is not a plain array') +
					', so there is no root provider list to add to that this capability can read',
			],
			frozen,
		);
	const last = providers.value.elements.filter((element: AstNode | null) => element !== null).at(-1);
	if (last === undefined)
		return refusal(
			[
				`${CALL_SET_DISABLED_STATE_TOKEN} was not provided: the bootstrapping ` +
					`@${NG_MODULE_DECORATOR} literal in ${module.path} declares an empty \`providers\` ` +
					'array, and this capability writes next to an existing provider rather than ' +
					'reformatting a list it cannot see the shape of',
