				[
					`${CALL_SET_DISABLED_STATE_TOKEN} was not provided: ${module.path} names no ` +
						`\`${FORMS_PACKAGE}\` import with braces to add the token to, and this capability ` +
						'writes into the declaration the application already has rather than adding a ' +
